import Foundation

/// Where an island's props hold an entity (spec §2.1). Generated by codegen, as an island type's
/// `islandEntities`.
public struct EntityPath: Sendable, Equatable {
    /// From the props down: property names, "[]" for an array's items, "{}" for a map's values.
    public let path: [String]
    public let entity: String
    /// The property that identifies one.
    public let id: String
    /// The entity's properties the island shows, the id among them.
    public let properties: [String]

    public init(path: [String], entity: String, id: String, properties: [String]) {
        self.path = path
        self.entity = entity
        self.id = id
        self.properties = properties
    }
}

/// What an action changed about one entity (spec §5.3): properties it set, or that it's gone.
public struct EntityChange: Decodable, Sendable, Equatable {
    public let entity: String
    public let id: String
    /// The properties that changed, with their new values. Empty for a deleted entity.
    public let set: [String: JSONValue]
    public let delete: Bool

    public init(entity: String, id: String, set: [String: JSONValue] = [:], delete: Bool = false) {
        self.entity = entity
        self.id = id
        self.set = set
        self.delete = delete
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        entity = try c.decode(String.self, forKey: .entity)
        id = try c.decode(String.self, forKey: .id)
        set = try c.decodeIfPresent([String: JSONValue].self, forKey: .set) ?? [:]
        delete = try c.decodeIfPresent(Bool.self, forKey: .delete) ?? false
    }

    private enum CodingKeys: String, CodingKey { case entity, id, set, delete }
}

/// An island's new entry, for the screen with these exact params (spec §5.3).
public struct IslandUpdate: Decodable, Sendable {
    public let screen: String
    public let params: [String: String]
    public let island: IslandEntry
}

/// What a client knows about the islands it can render: their versions, sent with every request,
/// and where their props hold entities, to apply an action's changes. Get it from a registry:
/// `registry.catalog`.
public struct IslandCatalog: Sendable {
    public let capabilities: [String: [Int]]
    let entityPaths: [String: [EntityPath]]

    public static let empty = IslandCatalog(capabilities: [:], entityPaths: [:])

    public init(capabilities: [String: [Int]], entityPaths: [String: [EntityPath]]) {
        self.capabilities = capabilities
        self.entityPaths = entityPaths
    }

    /// Where an island version's props hold entities.
    public func entities(type: String, version: Int) -> [EntityPath] {
        entityPaths["\(type)@\(version)"] ?? []
    }
}

/// One action's changes and updates (spec §5.3), applied the same way to every screen a client has.
public struct EffectsBatch: Sendable {
    public let effects: ActionEffects
    public let catalog: IslandCatalog

    public init(effects: ActionEffects, catalog: IslandCatalog) {
        self.effects = effects
        self.catalog = catalog
    }

    /// Whether there's anything for screens: changes or updates.
    public var touchesScreens: Bool { !effects.changes.isEmpty || !effects.update.isEmpty }

    /// A screen with the changes and updates applied, or nil when the client must reload it: a
    /// deleted entity held where it can't be removed, or an update the screen can't take.
    public func apply(to response: ScreenResponse, params: [String: String]) -> ScreenResponse? {
        var islands: [IslandEntry] = []
        for entry in response.islands {
            guard entry.status == "ok", let props = entry.props else {
                islands.append(entry)
                continue
            }
            var reload = false
            var changed = props
            for path in catalog.entities(type: entry.type, version: entry.version) {
                changed = applyAlong(changed, path: path, rest: path.path[...], inArray: false, reload: &reload)
            }
            if reload { return nil }
            islands.append(entry.with(props: changed))
        }
        for update in effects.update where update.screen == response.screen && update.params == params {
            guard let i = islands.firstIndex(where: { $0.key == update.island.key }),
                  islands[i].status != "pending", islands[i].type == update.island.type
            else { return nil }
            islands[i] = update.island
        }
        return response.with(islands: islands)
    }

    /// Applies the changes to the entities at the end of a path. Returns nil for an entity deleted
    /// from an array, and sets `reload` when one is deleted from anywhere else.
    private func applyAlong(
        _ value: JSONValue,
        path: EntityPath,
        rest: ArraySlice<String>,
        inArray: Bool,
        reload: inout Bool
    ) -> JSONValue {
        guard let step = rest.first else {
            guard case .object(var object) = value, case .string(let id)? = object[path.id],
                  let change = effects.changes.first(where: { $0.entity == path.entity && $0.id == id })
            else { return value }
            if change.delete {
                if !inArray { reload = true }
                return inArray ? .null : value
            }
            for (name, new) in change.set where path.properties.contains(name) {
                object[name] = new
            }
            return .object(object)
        }
        let next = rest.dropFirst()
        switch (step, value) {
        case ("[]", .array(let items)):
            let atEnd = next.isEmpty
            var kept: [JSONValue] = []
            for item in items {
                let changed = applyAlong(item, path: path, rest: next, inArray: atEnd, reload: &reload)
                // A deleted entity comes back as null, and leaves the list.
                if atEnd, changed == .null, item != .null { continue }
                kept.append(changed)
            }
            return .array(kept)
        case (_, .object(var object)):
            for key in object.keys where step == "{}" || step == key {
                if let item = object[key] {
                    object[key] = applyAlong(item, path: path, rest: next, inArray: false, reload: &reload)
                }
            }
            return .object(object)
        default:
            return value
        }
    }
}

extension IslandEntry {
    func with(props: JSONValue) -> IslandEntry {
        IslandEntry(key: key, type: type, version: version, status: status, props: props, error: error, strings: strings)
    }
}

extension ScreenResponse {
    func with(islands: [IslandEntry]) -> ScreenResponse {
        ScreenResponse(
            protocol: self.protocol, screen: screen, islands: islands, meta: meta, cache: cache, locale: locale, plurals: plurals
        )
    }
}
